<div class="row g-4 credit-card-interest-calculator-rebuilt"><div class="col-lg-12"><div class="calculator-card"><div class="calculator-body"><div class="row g-3"><div class="col-md-6"><label class="form-label-custom">Current Balance ($)</label><div class="input-group"><span class="input-group-text bg-light fw-bold">$</span><input type="number" id="cc-bal" class="form-control form-control-lg" value="5000" min="0"></div></div><div class="col-md-6"><label class="form-label-custom">APR (%)</label><div class="input-group"><input type="number" id="cc-apr" class="form-control form-control-lg" value="22" min="0"><span class="input-group-text bg-light fw-bold">%</span></div></div><div class="col-md-6"><label class="form-label-custom">Monthly Payment ($)</label><div class="input-group"><span class="input-group-text bg-light fw-bold">$</span><input type="number" id="cc-pmt" class="form-control form-control-lg" value="150" min="0"></div></div><div class="col-md-6"><label class="form-label-custom">New Charges ($/mo)</label><div class="input-group"><span class="input-group-text bg-light fw-bold">$</span><input type="number" id="cc-new" class="form-control form-control-lg" value="0" min="0"></div></div></div></div></div></div><div class="col-lg-12"><div class="output-card-themed" style="--tool-hue:0;--tool-color:#ef4444;--tool-bg:rgba(0,0,0,.02);"><div class="output-hero"><span class="output-hero-label">Credit Card Interest Calculator</span><div class="output-hero-value" id="credit-val">—</div><span class="output-hero-unit" id="credit-st">—</span></div><div class="row g-3 mt-3"><div class="col-md-3"><div class="stat-card" style="border-color:#ef4444;background:rgba(0,0,0,.02);"><span class="stat-card-label">MONTHLY INTEREST</span><span class="stat-card-value" style="color:#ef4444" id="cc-int">—</span></div></div><div class="col-md-3"><div class="stat-card" style="border-color:#3b82f6;background:rgba(0,0,0,.02);"><span class="stat-card-label">PAYOFF TIME</span><span class="stat-card-value" style="color:#3b82f6" id="cc-months">—</span></div></div><div class="col-md-3"><div class="stat-card" style="border-color:#f59e0b;background:rgba(0,0,0,.02);"><span class="stat-card-label">TOTAL INTEREST</span><span class="stat-card-value" style="color:#f59e0b" id="cc-total-i">—</span></div></div><div class="col-md-3"><div class="stat-card" style="border-color:#a855f7;background:rgba(0,0,0,.02);"><span class="stat-card-label">TOTAL PAID</span><span class="stat-card-value" style="color:#a855f7" id="cc-total">—</span></div></div></div><div class="mt-4" id="credit-ins"></div><div class="row g-2 mt-4"><div class="col-md-4"><button class="btn d-block mx-auto btn-dark py-3 px-4 fw-bold rounded-pill shadow-sm w-100" id="credit-cp"><i class="fas fa-copy me-2"></i>Copy Summary</button></div><div class="col-md-4"><button class="btn d-block mx-auto btn-outline-dark py-3 px-4 fw-bold rounded-pill shadow-sm w-100" id="credit-rs"><i class="fas fa-rotate-left me-2"></i>Reset</button></div><div class="col-md-4"><button class="btn d-block mx-auto btn-outline-primary py-3 px-4 fw-bold rounded-pill shadow-sm w-100" id="credit-cb"><i class="fas fa-calculator me-2"></i>Calculate</button></div></div></div></div></div>
<script>document.addEventListener("DOMContentLoaded",function(){const $=id=>document.getElementById(id);function fmt(v){return"$"+Math.round(v).toLocaleString();}function calc(){const bal=parseFloat($("cc-bal").value)||0,apr=(parseFloat($("cc-apr").value)||0)/100/12,pmt=parseFloat($("cc-pmt").value)||1,nc=parseFloat($("cc-new").value)||0;const moInt=bal*apr;let b=bal,m=0,ti=0;while(b>0&&m<600){const i=b*apr;ti+=i;b=b+i+nc-pmt;m++;if(b<0)b=0;}$("credit-val").textContent=fmt(moInt)+"/mo";$("cc-int").textContent=fmt(moInt);$("cc-months").textContent=m>=600?"∞":m+" mo";$("cc-total-i").textContent=fmt(ti);$("cc-total").textContent=fmt(ti+bal);$("credit-st").textContent=m<600?"PAYOFF PROJECTED":"NEVER PAYOFF";$("credit-st").style.color=m<600?"#22c55e":"#ef4444";let ins=[];ins.push("Monthly interest: <strong>"+fmt(moInt)+"</strong> at "+parseFloat($("cc-apr").value)+"% APR.");ins.push(m<600?"Payoff in <strong>"+m+" months</strong>. Total interest: <strong>"+fmt(ti)+"</strong>.":"⚠️ Balance never pays off at current payment level.");$("credit-ins").innerHTML='<h6 class="fw-bold mb-2"><i class="fas fa-lightbulb me-2 text-warning"></i>Analysis</h6><ul class="list-unstyled mb-0 small">'+ins.map(x=>'<li class="mb-2"><i class="fas fa-check-circle text-success me-2"></i>'+x+'</li>').join("")+'</ul>';}['cc-bal','cc-apr','cc-pmt','cc-new'].forEach(id=>$(id).addEventListener("input",calc));$("credit-cb").addEventListener("click",calc);$("credit-cp").addEventListener("click",function(){navigator.clipboard.writeText("Credit Card Interest Calculator: "+$("credit-val").textContent).then(()=>{const o=this.innerHTML;this.innerHTML='<i class="fas fa-check me-2"></i>Copied!';setTimeout(()=>this.innerHTML=o,2e3);});});$("credit-rs").addEventListener("click",()=>{$("cc-bal").value=5000;$("cc-apr").value=22;$("cc-pmt").value=150;$("cc-new").value=0;calc();});calc();});</script>
<style>.credit-card-interest-calculator-rebuilt .calculator-card{background:#fff;border:1px solid #e5e7eb;border-radius:20px;padding:2rem;box-shadow:0 4px 24px rgba(0,0,0,.04)}.credit-card-interest-calculator-rebuilt .calculator-header{display:flex;align-items:center;gap:1.25rem;margin-bottom:2rem}.credit-card-interest-calculator-rebuilt .calculator-header h4{margin:0;font-weight:700;font-size:1.1rem;color:#1e293b}.credit-card-interest-calculator-rebuilt .calculator-header p{margin:0;font-size:.85rem;color:#64748b}.credit-card-interest-calculator-rebuilt .tool-icon-circle{width:56px;height:56px;border-radius:14px;display:flex;align-items:center;justify-content:center;font-size:1.4rem;flex-shrink:0}.credit-card-interest-calculator-rebuilt .form-label-custom{font-size:.75rem;font-weight:700;color:#475569;text-transform:uppercase;letter-spacing:.8px;margin-bottom:.4rem;display:block}</style><?php /**PATH D:\Xamp\htdocs\ToolsHub\resources\views\tools\interactive\credit-card-interest-calculator.blade.php ENDPATH**/ ?>